      "supportingQuote": "Theo báo cáo vĩ mô tháng 11 của Công ty Chứng khoán Yuanta Việt Nam, sản xuất công nghiệp tiếp tục khởi sắc.",
      "facts": [],
      "sectionA_whatHappened": "Sản xuất công nghiệp khởi sắc, vốn FDI giải ngân cao nhất 5 năm, đầu tư công tăng tốc đang mở thêm dư địa tăng trưởng cho nhiều ngành. Trên thị trường chứng khoán, dòng cổ phiếu nào có thể đón đầu những động lực này?",
      "sectionB_context": "Việt Nam tiếp tục thu hút nguồn vốn đầu tư hạ tầng logistics chiến lược và mở rộng quan hệ hợp tác công nghệ bán dẫn với các tập đoàn công nghiệp hàng đầu khu vực.",
      "sectionC_whyItMatters": "Dữ kiện quy mô (Sản xuất khởi sắc, cơ hội lớn gọi tên nhóm cổ phiếu nào?) giải tỏa điểm nghẽn lưu thông logistics, thúc đẩy chuỗi cung ứng công nghệ cao và mở rộng khả năng tiếp cận vốn đầu tư dài hạn.",
      "sectionD_macroMicro": "Quy hoạch hạ tầng & Chiến lược FDI (Báo Tuổi Trẻ) → Doanh nghiệp đầu tư giải ngân vốn xây dựng & công nghệ → Doanh nghiệp phụ trợ và nhà thầu tiếp cận dòng tiền dự án → Gia tăng việc làm và giao dịch thanh toán B2B.",
      "sectionE_fintechLens": "Ứng dụng giải pháp Quản lý dòng tiền số (Cash Management) và Tài trợ chuỗi cung ứng (Supply Chain Finance) cho các nhà thầu hạ tầng và đối tác công nghệ cao.",
      "sectionF_scenariosWatchlist": "Theo dõi sát biến động tiếp theo của dữ kiện (Sản xuất khởi sắc, cơ hội lớn gọi tên nhóm cổ phiếu nào?) và các bước điều hành của cơ quan quản lý trong các phiên tới.",
      "sectionG_practicalTakeaway": "Tối ưu hóa quy trình luân chuyển dòng tiền, hạn chế lưu trữ tiền mặt và khai thác các kênh tài trợ vốn số hóa.",
