      "sectionB_context": "Ngân hàng Nhà nước và hệ thống NHTM duy trì điều hành thanh khoản linh hoạt, kiểm soát biến động tỷ giá và cân đối hài hòa mặt bằng lãi suất huy động - cho vay.",
