      "sectionD_macroMicro": "Điều hành tiền tệ & Thanh khoản NHNN (ACB) → Hệ thống NHTM điều chỉnh lãi suất huy động và chỉ tiêu tín dụng → Doanh nghiệp tối ưu chi phí lãi vay và kế hoạch vốn lưu động → Người dân tiếp cận vốn vay sản xuất kinh doanh.",
