      "summary": "Bộ Công thương đã công bố thông tin điều hành, bảng giá xăng dầu mới nhất, yêu cầu các doanh nghiệp áp dụng từ 15 giờ hôm nay 12.11.",
      "category": "Bán lẻ, D2C và xu hướng tiêu dùng",
