      "pageTitle": "TP.HCM vào mùa 'sale', nhưng săn thế nào cho đáng tiền?",
      "headline": "TP.HCM vào mùa 'sale', nhưng săn thế nào cho đáng tiền?",
      "summary": "TP.HCM khởi động chương trình kích cầu mua sắm “Vibrant Ho Chi Minh City - Shopping Season 2026” với hàng loạt chương trình khuyến mãi, ưu đãi trị giá hơn 250 tỉ đồng. Trước rừng khuyến mãi này, người tiêu dùng làm sao để không mua hớ, không ham rẻ mà chọn được sản phẩm chất lượng?",
